let t = 0;
let d;

setup = _ => {
	let c = createCanvas(w = displayWidth, h = displayHeight);
	d = c.drawingContext
  setInterval(i => o(t++/60),16);
}

o = t => {
	d.fillStyle = "rgb(80, 0, 0, 0.1)";
	d.fillRect(0, 0, w, h);
	for (i = 1e4; i--;) {
		d.clearRect(w/2 + cos(p = tan(i * i - t / 9)) / (q = (i / sin(t + i + p) + i * p * i / 180) / i / i) * 5, h/2 + sin(p) / q, l = 3 * sin(i), l)
	}
}

